# Two Sum - Python 3
def two_sum(nums, target):
    # Write your solution here
    seen = {}
    for i, num in enumerate(nums):
        diff = target - num
        if diff in seen:
            return [seen[diff], i]
        seen[num] = i
    return []

def main():
    n = int(input())
    nums = list(map(int, input().split()))
    target = int(input())
    result = two_sum(nums, target)
    print(f"{result[0]} {result[1]}")

if __name__ == "__main__":
    main()

