int main() {
    char s[100005];
    if (fgets(s, sizeof(s), stdin) == NULL) return 0;
    s[strcspn(s, "\r\n")] = 0;
    int len = strlen(s);

    // Write your solution here
    for (int i = 0; i < len / 2; i++) {
        char temp = s[i];
        s[i] = s[len - 1 - i];
        s[len - 1 - i] = temp;
    }
    printf("%s\n", s);
    return 0;
}

